effect.shader:
const float PI = 3.14159265;
void main() {
    float a = angle * PI / 180.0;
    vec2 d = vec2(cos(a), sin(a)) * offset;
    d.x /= max(acAspect, 1e-4);
    vec4 o  = texture(inputImg, acScreenNorm);
    vec4 l  = texture(inputImg, acScreenNorm - d);
    vec4 r  = texture(inputImg, acScreenNorm + d);
    vec4 dupla = (l + r) * 0.5;
    fragColor = mix(o, dupla, mistura);
}
